/**
 * generate-agents-panels.mjs
 *
 * Scans src/app/agents/_components/*Panel.tsx for a `panelMeta` export and
 * writes the ordered registry to panels.generated.tsx. Adding a new panel
 * only means adding a `panelMeta` export to the new panel file — page.tsx
 * and this generated file need no manual edit (see task #675).
 *
 * Exits non-zero if two panels declare the same `panelMeta.id`.
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const ROOT = path.join(__dirname, '..');
const COMPONENTS_DIR = path.join(ROOT, 'src', 'app', 'agents', '_components');
const OUT_FILE = path.join(COMPONENTS_DIR, 'panels.generated.tsx');

const PANEL_META_RE =
  /export const panelMeta:\s*PanelMeta\s*=\s*\{\s*id:\s*'([^']+)'\s*,\s*order:\s*(-?\d+)\s*\}/;

/**
 * Scans a directory for `*Panel.tsx` files (excluding tests) that export a
 * `panelMeta` const, and returns them ordered by `order` then `id`.
 * @param {string} componentsDir - Absolute path to the panel components directory
 * @returns {{ id: string; order: number; componentName: string; file: string }[]}
 */
export function discoverPanels(componentsDir) {
  const files = fs
    .readdirSync(componentsDir)
    .filter((f) => f.endsWith('Panel.tsx') && !f.includes('.test.'));

  const panels = [];
  const seenIds = new Map();

  for (const file of files) {
    const contents = fs.readFileSync(path.join(componentsDir, file), 'utf8');
    const match = contents.match(PANEL_META_RE);
    if (!match) continue;

    const [, id, orderStr] = match;
    const order = Number(orderStr);
    const componentName = path.basename(file, '.tsx');

    if (seenIds.has(id)) {
      throw new Error(
        `generate-agents-panels: duplicate panel id "${id}" (${file} and ${seenIds.get(id)})`,
      );
    }
    seenIds.set(id, file);

    panels.push({ id, order, componentName, file });
  }

  panels.sort((a, b) => a.order - b.order || a.id.localeCompare(b.id, 'en'));
  return panels;
}

/**
 * Renders the panels.generated.tsx file contents for a discovered panel list.
 * @param {{ id: string; componentName: string }[]} panels
 * @returns {string}
 */
export function renderRegistry(panels) {
  const imports = panels
    .map((p) => `import { ${p.componentName} } from './${p.componentName}';`)
    .join('\n');
  const entries = panels
    .map((p) => `  { id: '${p.id}', Component: ${p.componentName} },`)
    .join('\n');

  return (
    `/**\n` +
    ` * panels.generated\n` +
    ` *\n` +
    ` * Auto-generated by scripts/generate-agents-panels.mjs — do not edit by hand.\n` +
    ` * Regenerate after adding/removing a panel's \`panelMeta\` export.\n` +
    ` */\n` +
    `import type { ComponentType } from 'react';\n` +
    `${imports}\n\n` +
    `export const AGENTS_PANELS: { id: string; Component: ComponentType }[] = [\n${entries}\n];\n`
  );
}

function main() {
  const panels = discoverPanels(COMPONENTS_DIR);
  fs.writeFileSync(OUT_FILE, renderRegistry(panels), 'utf8');
  console.log(
    `generate-agents-panels: ${panels.length} panels -> ${path.relative(ROOT, OUT_FILE)}`,
  );
}

// NOTE: Guards CLI execution so the module can be imported as pure functions in tests.
if (import.meta.url === pathToFileURL(process.argv[1] ?? '').href) {
  try {
    main();
  } catch (err) {
    console.error(err instanceof Error ? err.message : err);
    process.exit(1);
  }
}
